import fam as F, numpy as np, pandas as pd
from sklearn.ensemble import RandomForestRegressor
from sklearn.kernel_ridge import KernelRidge
from scipy.stats import spearmanr
tr,po=F.load(); els=F.els
tr['fam']=tr.apply(F.fam,axis=1); po['fam']=po.apply(F.fam,axis=1)
tr['ly']=np.log(tr['target']+1e-6)
tr=tr[tr.target<5].copy()   # drop the zT=21.6 outlier

def fit_slopes(d, prior=0.0078, k=8.0):
    """shrunk per-family slope in log(zT) per K"""
    out={}
    for f,s in d.groupby('fam'):
        if s['T'].nunique()>1 and len(s)>=4:
            b=np.polyfit(s['T'],s['ly'],1)[0]
            n=len(s)
        else:
            b=prior; n=0
        out[f]=(n*b+k*prior)/(n+k)
    return out, prior

def build(d, Ttarget, slopes=None, prior=0.0078, mode='slope'):
    if mode=='none':
        base=d['ly'].values; 
        sl=np.zeros(len(d))
    else:
        sl=np.array([slopes[0].get(f,prior) for f in d['fam']])
    base=d['ly'].values - sl*(d['T'].values-Ttarget)
    return base

def run(trn, tst, mode, prior=0.0078, k=8.0, model='rf'):
    Tt=tst['T'].iloc[0]
    slopes=fit_slopes(trn,prior,k)
    if mode=='none':
        base=trn['ly'].values
    else:
        sl=np.array([slopes[0].get(f,prior) for f in trn['fam']])
        base=trn['ly'].values - sl*(trn['T'].values-Tt)
    if model=='rf':
        m=RandomForestRegressor(600,random_state=0,min_samples_leaf=1)
    else:
        m=KernelRidge(alpha=0.3,kernel='laplacian',gamma=3.0)
    m.fit(trn[els].values,base)
    p=m.predict(tst[els].values)
    return p, slopes
EOF
python -c "
from val import *
trn=tr[tr.T_ if False else tr['T']<=400]; tst=tr[tr['T']==500]
y=tst['ly'].values
for mode in ['none','slope']:
  for prior in [0.004,0.0078,0.012]:
    for model in ['rf','krr']:
      p,_=run(trn,tst,mode,prior,model=model)
      top5=np.argsort(-p)[:5]
      print(mode,prior,model,'sp=%.3f'%spearmanr(p,y).correlation,'top5 mean rank pct=%.2f'%np.mean([(y<y[i]).mean() for i in top5]),'top5 zT',np.round(np.exp(y[top5]),3))
" 2>/dev/null

